// recortes-vista-superior v3
// Dibuja los recortes de la ranura K y galería (Alt+K) desde una vista superior (planta X-Z),
// pintando la textura real / canvas completo de la cara superior de cada bloque (+Y) con pixel art nítido,
// micro-sombreado por altura de relieve y bordes definidos.
//
// API:
//   game.recortesVistaSuperior.on()      activa
//   game.recortesVistaSuperior.off()     restaura el render original
//   game.recortesVistaSuperior.estado()  info
//
(() => {
'use strict';

const origDibujaRecorte = window.mcDibujaRecorte;
if (typeof origDibujaRecorte !== 'function') throw new Error('recortes-vista-superior: no encuentro mcDibujaRecorte');

let activo = false;

// Obtiene canvas de la textura de la cara superior (+Y = cara 0)
function texFaceImg(val){
  const v = String(val);
  if (v.slice(0, 4) === 'tex:') {
    const key = v.slice(4);
    if (typeof getTexFaces === 'function') {
      const fc = getTexFaces(key);
      if (fc && fc.faces && fc.faces[0]) return { img: fc.faces[0], avg: fc.avg[0] };
    }
  }
  return null;
}

function dibujaRecorteSuperior(cv, r){
  if(!cv) return;
  const cx = cv.getContext('2d');
  cx.clearRect(0, 0, cv.width, cv.height);
  if(!r || !r.cells || !r.cells.length) return;

  cx.imageSmoothingEnabled = false;

  const d = typeof mcRecorteDim === 'function' ? mcRecorteDim(r) : { w: 1, d: 1, h: 1 };
  const w = Math.max(1, d.w);
  const depth = Math.max(1, d.d);

  const p = Math.max(1, Math.floor(Math.min(cv.width / w, cv.height / depth)));
  const ox = Math.floor((cv.width - w * p) / 2);
  const oy = Math.floor((cv.height - depth * p) / 2);

  // De abajo hacia arriba (dz menor a mayor) para que las capas superiores tapen a las inferiores
  const cel = r.cells.slice().sort((a, b) => (a.dz - b.dz));

  for(const c of cel){
    const px = ox + c.dx * p;
    const py = oy + c.dy * p;
    const tf = texFaceImg(c.c);

    if(tf && tf.img){
      // Dibuja la textura detallada (16x16 pixel art real de la cara superior)
      cx.drawImage(tf.img, px, py, p, p);
    } else {
      // Fallback a color sólido si no es textura
      const colHex = (tf && tf.avg) || (typeof texRepr === 'function' && String(c.c).startsWith('tex:') ? texRepr(String(c.c).slice(4)) : String(c.c));
      const rgb = mcHexRGB(colHex);
      cx.fillStyle = 'rgb(' + (rgb[0]*255|0) + ',' + (rgb[1]*255|0) + ',' + (rgb[2]*255|0) + ')';
      cx.fillRect(px, py, p, p);
    }

    // Sombreado de relieve según altura (dz): capas más altas más luminosas, más bajas ligeramente más oscuras
    if(d.h > 1){
      const t = 0.82 + 0.18 * (c.dz / (d.h - 1));
      if(t < 0.98){
        cx.fillStyle = 'rgba(0,0,0,' + (1 - t).toFixed(2) + ')';
        cx.fillRect(px, py, p, p);
      }
    }

    // Línea sutil de separación si el tamaño de bloque lo permite
    if(p >= 8){
      cx.strokeStyle = 'rgba(0,0,0,0.12)';
      cx.strokeRect(px + 0.5, py + 0.5, p - 1, p - 1);
    }
  }
}

function refrescarUI(){
  if (typeof mcPintaSlotRecortes === 'function') mcPintaSlotRecortes();
  if (typeof mcRenderRecortes === 'function' && typeof mcRecortesAbierta === 'function' && mcRecortesAbierta()) {
    mcRenderRecortes();
  }
}

function instalar(){
  window.mcDibujaRecorte = dibujaRecorteSuperior;
  activo = true;
  refrescarUI();
}

function desinstalar(){
  window.mcDibujaRecorte = origDibujaRecorte;
  activo = false;
  refrescarUI();
}

function estado(){
  const s = 'recortes-vista-superior: ' + (activo ? 'ACTIVO (vista en planta texturizada en alta definición)' : 'inactivo');
  console.log(s);
  return s;
}

const API = {
  on(){ if(!activo) instalar(); return 'recortes-vista-superior activado'; },
  off(){ if(activo) desinstalar(); return 'recortes-vista-superior desactivado'; },
  estado
};
game.recortesVistaSuperior = API;
API.on();
})();
